Notation DEP        := 2143064 (only parsing).   (* [comment removed for export] *)
Notation DEP_NUI    := 6337368 (only parsing).   (* [comment removed for export] *)
Notation DEP_MAP1   := 6337384 (only parsing).   (* [comment removed for export] *)
Notation SSB        := 2077512 (only parsing).   (* [comment removed for export] *)
Notation SSB_DATA   := 2077528 (only parsing).   (* [comment removed for export] *)
Notation SSB_STORED := 2077536 (only parsing).   (* [comment removed for export] *)
Notation LIM_IDS    := 65536 (only parsing).     (* [comment removed for export] *)
Notation LIM_FRAMES := 262144 (only parsing).    (* [comment removed for export] *)
Notation MASK20     := 1048575 (only parsing).
Definition bucket (h : Z) : Z := Z.land h MASK20.

Lemma bucket_range : forall h, 0 <= bucket h < 2^20.
Proof.
  intros h. unfold bucket. change 1048575 with (Z.ones 20). rewrite Z.land_ones by lia.
  apply Z.mod_pos_bound. lia.
Qed.

