Lemma d_K_insert : forall d h n, 0 <= d_ids d -> d_K (d_insert d h n) = d_K d ++ [h].
Proof.
  intros d h n Hi. unfold d_K, idseq. cbn [d_ids d_hash d_insert].
  replace (Z.to_nat (d_ids d + 1)) with (Z.to_nat (d_ids d) + 1)%nat by lia.
  rewrite seq_app, !map_app. cbn [map seq]. f_equal.
  - apply map_ext_in. intros id Hin. apply in_idseq in Hin. destruct (Z.eqb_spec id (d_ids d + 1)); [lia|reflexivity].
  - replace (Z.of_nat (1 + Z.to_nat (d_ids d))) with (d_ids d + 1) by lia. rewrite Z.eqb_refl. reflexivity.
Qed.

Lemma d_put_K : forall d h n, d_wf d ->
  d_K (d_put d h n) = (if existsb (Z.eqb h) (d_K d) then d_K d else d_K d ++ [h]).
Proof.
  intros d h n W. unfold d_put.
  destruct (Z.eqb_spec (d_find d h) 0) as [E|E].
  - replace (existsb (Z.eqb h) (d_K d)) with false. { apply d_K_insert. pose proof (wf_ids d W). lia. }
    symmetry. apply Bool.not_true_iff_false. rewrite existsb_exists. intros (x & Hin & Hx). apply Z.eqb_eq in Hx. subst x.
    apply (proj2 (d_find_K d h W)) in Hin. congruence.
  - replace (existsb (Z.eqb h) (d_K d)) with true; [reflexivity|]. symmetry. apply existsb_exists. exists h.
    split; [|apply Z.eqb_refl]. apply (d_find_K d h W). exact E.
Qed.

Lemma d_K_nodup : forall d, d_wf d -> (forall id id', 1 <= id <= d_ids d -> 1 <= id' <= d_ids d -> d_hash d id = d_hash d id' -> id = id') -> List.NoDup (d_K d).
Proof.
  intros d W INJ. unfold d_K. apply NoDup_map_NoDup_ForallPairs.
  - intros x y Hx Hy E. apply in_idseq in Hx. apply in_idseq in Hy. apply INJ; assumption.
  - unfold idseq. apply NoDup_map_NoDup_ForallPairs; [intros ? ? ? ?; lia| apply seq_NoDup].
Qed.

