  rw_cells segs m' SSB [C8 (wz (d_frames d + n + 1))] ->
  rw_cells segs m' SSB_STORED [C4 (wz (d_frames d + n + 1))] ->
  u8arr segs m' (d_sb d + 8 * d_frames d) junk -> Z.of_nat (length junk) = 8 * (LIM_FRAMES - d_frames d) ->
